<template><q-page class="customer-flow-page"><div class="page-heading"><div><div class="eyebrow">WE'RE HERE TO HELP</div><h1 class="page-title">Help & support</h1><p class="page-subtitle">Find answers or send a request to bank staff.</p></div><q-btn flat icon="refresh" label="Refresh" @click="load" /></div><section class="customer-panel"><q-expansion-item label="How do I recover my password?" icon="lock"><p class="q-pa-md">Ask bank staff to verify your identity and reset your password. Your authenticator remains enabled. If you lost it, use an unused recovery code from setup. Never send passwords, PINs, or recovery codes in a support request.</p></q-expansion-item><q-expansion-item label="How do I receive or scan a QR code?" icon="qr_code"><p class="q-pa-md">Open My account → Receive to save or share your code and optionally set an amount. Open Send funds → Scan QR to use the camera or upload a QR image. You still review the recipient before confirming payment.</p></q-expansion-item><q-expansion-item label="Why is a deposit or other-bank transfer pending?" icon="schedule"><p class="q-pa-md">Staff approves deposit/withdrawal requests and settles other-bank transfers. Rejected other-bank transfers are refunded. Check Activity alerts and your transaction history for updates.</p></q-expansion-item></section><q-banner v-if="error" class="bank-feedback q-my-md">{{ error }}</q-banner><div class="customer-workspace-grid q-mt-lg"><section class="customer-panel"><h2 class="section-heading">New support request</h2><q-form ref="ticketForm" class="customer-form" @submit="submit"><q-input v-model.trim="subject" filled label="Subject" maxlength="100" :rules="[v=>v.length>=3||'Enter a subject']" /><q-input v-model.trim="message" filled type="textarea" label="How can we help?" maxlength="2000" :rules="[v=>v.length>=10||'Describe the issue in at least 10 characters']" /><p class="page-subtitle">Do not include passwords, PINs, or authenticator codes.</p><q-btn color="primary" label="Send request" type="submit" :loading="busy" /></q-form></section><section class="customer-panel"><h2 class="section-heading">{{ auth.isCustomer ? 'Your requests' : 'Support queue' }}</h2><q-list separator><q-item v-for="ticket in tickets" :key="ticket.id"><q-item-section><q-item-label>#{{ ticket.id }} · {{ ticket.subject }}</q-item-label><q-item-label caption style="white-space:pre-wrap;overflow-wrap:anywhere">{{ ticket.message }}</q-item-label><q-item-label v-if="ticket.reply" class="q-mt-sm" style="white-space:pre-wrap;overflow-wrap:anywhere">Staff reply: {{ ticket.reply }}</q-item-label><q-item-label caption>{{ ticket.status }}</q-item-label><q-btn v-if="!auth.isCustomer && ticket.status==='OPEN'" flat label="Reply and resolve" @click="resolve(ticket)" /></q-item-section></q-item></q-list><p v-if="!tickets.length" class="page-subtitle">No support requests yet.</p></section></div><StaffPasswordReset v-if="!auth.isCustomer" /></q-page></template>
<script setup>
import {ref,onMounted,nextTick} from 'vue'
import {useQuasar} from 'quasar'
import {useAuthStore} from '@/stores/auth-store'
import api from '@/services/api'
import StaffPasswordReset from '@/components/StaffPasswordReset.vue'
const auth=useAuthStore(),$q=useQuasar(),tickets=ref([]),subject=ref(''),message=ref(''),error=ref(''),busy=ref(false),ticketForm=ref(null)
async function load(){error.value='';try{tickets.value=(await api.get('/support/tickets/')).data}catch{error.value='Could not load support requests. Please refresh.'}}
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{await api.post('/support/tickets/',{subject:subject.value,message:message.value});subject.value='';message.value='';await nextTick();ticketForm.value?.resetValidation();await load();$q.notify({type:'positive',message:'Support request sent'})}catch(e){error.value=e.response?.data?.detail||'Could not send request.'}finally{busy.value=false}}
function resolve(ticket){$q.dialog({title:'Reply to customer',prompt:{model:'',type:'textarea',isValid:v=>v.trim().length>=3&&v.length<=2000},cancel:true}).onOk(async reply=>{try{await api.post(`/support/tickets/${ticket.id}/resolve`,{reply});await load()}catch(e){error.value=e.response?.data?.detail||'Could not resolve request.'}})}
onMounted(load)
</script>
